const JobDB=(()=>{const NAME='job-stage-v3',VER=2;let db;function open(){return new Promise((ok,no)=>{if(db)return ok(db);let r=indexedDB.open(NAME,VER);r.onupgradeneeded=()=>{let d=r.result;if(!d.objectStoreNames.contains('jobs'))d.createObjectStore('jobs',{keyPath:'id'});if(!d.objectStoreNames.contains('files')){let s=d.createObjectStore('files',{keyPath:'id'});s.createIndex('jobId','jobId')}if(!d.objectStoreNames.contains('records')){let s=d.createObjectStore('records',{keyPath:'id'});s.createIndex('jobId','jobId')}};r.onsuccess=()=>{db=r.result;ok(db)};r.onerror=()=>no(r.error)})}async function store(n,m='readonly'){let d=await open();return d.transaction(n,m).objectStore(n)}function req(r){return new Promise((ok,no)=>{r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)})}async function allJobs(){return req((await store('jobs')).getAll())}async function putJob(j){return req((await store('jobs','readwrite')).put(j))}async function deleteJob(id){let d=await open(),tx=d.transaction(['jobs','files','records'],'readwrite');tx.objectStore('jobs').delete(id);let ix=tx.objectStore('files').index('jobId'),range=IDBKeyRange.only(id);ix.openCursor(range).onsuccess=e=>{let c=e.target.result;if(c){c.delete();c.continue()}};let rx=tx.objectStore('records').index('jobId');rx.openCursor(range).onsuccess=e=>{let c=e.target.result;if(c){c.delete();c.continue()}};return new Promise((ok,no)=>{tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}async function records(jobId){return req((await store('records')).index('jobId').getAll(jobId))}async function putRecord(rec){rec.id=rec.id||crypto.randomUUID();rec.updatedAt=new Date().toISOString();await req((await store('records','readwrite')).put(rec));return rec}async function deleteRecord(id){return req((await store('records','readwrite')).delete(id))}async function files(jobId){return req((await store('files')).index('jobId').getAll(jobId))}async function putFile(jobId,file,meta={}){let rec={id:crypto.randomUUID(),jobId,name:file.name,type:file.type,size:file.size,addedAt:new Date().toISOString(),category:meta.category||'Other',amount:meta.amount||0,blob:file};await req((await store('files','readwrite')).put(rec));return rec}async function deleteFile(id){return req((await store('files','readwrite')).delete(id))}async function backup(){let j=await allJobs(),d=await open(),fs=await req(d.transaction('files').objectStore('files').getAll()),rs=await req(d.transaction('records').objectStore('records').getAll());let out={schema:'JOB_STAGE_BACKUP_V2',createdAt:new Date().toISOString(),jobs:j,records:rs,files:[]};for(const f of fs){let buf=await f.blob.arrayBuffer();out.files.push({...f,blob:undefined,data:btoa(String.fromCharCode(...new Uint8Array(buf)))})}return new Blob([JSON.stringify(out)],{type:'application/json'})}async function restore(obj){if(!['JOB_STAGE_BACKUP_V1','JOB_STAGE_BACKUP_V2'].includes(obj.schema))throw Error('Invalid Job Stage backup');let d=await open(),tx=d.transaction(['jobs','files','records'],'readwrite');tx.objectStore('jobs').clear();tx.objectStore('files').clear();tx.objectStore('records').clear();obj.jobs.forEach(j=>tx.objectStore('jobs').put(j));(obj.records||[]).forEach(r=>tx.objectStore('records').put(r));for(const f of obj.files||[]){let bytes=Uint8Array.from(atob(f.data),c=>c.charCodeAt(0));tx.objectStore('files').put({...f,data:undefined,blob:new Blob([bytes],{type:f.type||''})})}return new Promise((ok,no)=>{tx.oncomplete=ok;tx.onerror=()=>no(tx.error)})}return{open,allJobs,putJob,deleteJob,records,putRecord,deleteRecord,files,putFile,deleteFile,backup,restore}})();